def merge(intervals):
    out = []
    for s, e in sorted(intervals, key=lambda x: x[0]):
        if not out or s > out[-1][1]:
            out.append([s, e])
        else:
            out[-1][1] = max(out[-1][1], e)
    return out

import heapq

def min_rooms(meetings):
    meetings = sorted(meetings, key=lambda m: m[0])
    ends = []
    for s, e in meetings:
        if ends and ends[0] <= s:
            heapq.heappop(ends)
        heapq.heappush(ends, e)
    return len(ends)

def in_subnet(ip, network, prefix_len):
    mask = (0xFFFFFFFF << (32 - prefix_len)) & 0xFFFFFFFF
    return (ip & mask) == (network & mask)

def popcount(n):
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

